const DEV_SHARE_MAX_BYTES = 512 * 1024;
const DEV_SHARE_ID_BYTES = 9;
const DEV_SHARE_ID_PATTERN = /^[A-Za-z0-9_-]{8,32}$/;
const devShareStore = new Map<string, unknown>();

function compactDevShareId() {
  return randomBytes(DEV_SHARE_ID_BYTES).toString('base64url');
}

function readRequestBody(req: http.IncomingMessage): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('error', reject);
    req.on('end', () => resolve(Buffer.concat(chunks)));
  });
}

function sendJson(res: http.ServerResponse, statusCode: number, body: unknown) {
  res.statusCode = statusCode;
  res.setHeader('content-type', 'application/json');
  res.end(JSON.stringify(body));
}

function validateDevSharedSession(value: any): string | null {
  if (!value || typeof value !== 'object') return 'Expected shared session object';
  if (typeof value.title !== 'string' || !value.title.trim()) return 'Missing shared session title';
  if (!Array.isArray(value.messages) || value.messages.length === 0) return 'Missing shared session messages';
  if (value.id !== undefined && (typeof value.id !== 'string' || !DEV_SHARE_ID_PATTERN.test(value.id))) {
    return 'Invalid shared session id';
  }
  for (const message of value.messages) {
    const role = message?.role;
    if (role !== 'user' && role !== 'user-with-attachments' && role !== 'assistant') {
      return 'Invalid shared session message role';
    }
    if (!Array.isArray(message?.content)) return 'Invalid shared session message content';
  }
  return null;
}

function chatProxyPlugin(): Plugin {
  return {
    name: 'chat-proxy',
    configureServer(server) {
      server.middlewares.use(async (req, res, next) => {
        const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;

        // Nitro serves /api/share in production. Vite dev needs the same
        // endpoint; otherwise the browser falls back to a massive compressed
        // hash URL, which is exactly what makes Discord sharing unreasonable.
        if (pathname === '/api/share') {
          if (req.method !== 'POST') {
            sendJson(res, 405, { error: 'Method not allowed' });
            return;
          }

          try {
            const bodyBuffer = await readRequestBody(req);
            if (bodyBuffer.byteLength > DEV_SHARE_MAX_BYTES) {
              sendJson(res, 413, { error: 'Shared session is too large' });
              return;
            }

            const body = JSON.parse(bodyBuffer.toString('utf8'));
            const validationError = validateDevSharedSession(body);
            if (validationError) {
              sendJson(res, 400, { error: validationError });
              return;
            }

            let id = compactDevShareId();
            for (let attempt = 0; attempt < 4 && devShareStore.has(id); attempt++) {
              id = compactDevShareId();
            }

            const shared = {
              ...body,
              id,
              schemaVersion: 2,
              messageCount: body.messages.length,
            };
            devShareStore.set(id, shared);
            sendJson(res, 200, { id });
          } catch (error) {
            sendJson(res, 400, { error: error instanceof Error ? error.message : 'Invalid shared session payload' });
          }
          return;
        }

        if (pathname.startsWith('/api/share/')) {
          if (req.method !== 'GET') {
            sendJson(res, 405, { error: 'Method not allowed' });
            return;
          }

          const id = decodeURIComponent(pathname.replace(/^\/api\/share\//, ''));
          if (!DEV_SHARE_ID_PATTERN.test(id)) {
            sendJson(res, 400, { error: 'Invalid shared session id' });
            return;
          }

          const shared = devShareStore.get(id);
          if (!shared) {
            sendJson(res, 404, { error: 'Shared session not found' });
            return;
